        <div class="row">
            <!--PANEL MIS COMPRAS-->
            <app-mis-compras></app-mis-compras>
            <!--PANEL ADMIN-->
            <app-panel-admin></app-panel-admin>
            <div *ngFor="let pienso of piensoService.piensos" class="col-md-4" style="margin-bottom: 3%">
              <app-producto [piensoEnviado]="pienso"></app-producto>
            </div>
        </div>

    </div>
